{
  "questions": [
    {
      "question_id": "q1",
      "question": "What does the petroleum liquid look like at the intended measurement point?"
    },
    {
      "question_id": "q2",
      "question": "What are the cable route and length between the measurement point and analyzer location, and could an analyzer or sensor be installed near the process?"
    },
    {
      "question_id": "q3",
      "question": "Is the water-content result intended for research, a pilot line or production?"
    },
    {
      "question_id": "q4",
      "question": "Do you have a reference method that can provide comparison values for water content?"
    },
    {
      "question_id": "q5",
      "question": "Have you defined numerical acceptance criteria for water-content measurement, such as accuracy or a detection limit?"
    },
    {
      "question_id": "q6",
      "question": "Over what water-content range must the measurement follow changes?"
    }
  ],
  "plan": {
    "objective": "Screen candidate methods on retained petroleum samples to assess water-content measurement feasibility before considering an in-line configuration.",
    "samples_and_states": [
      {
        "text": "Select retained petroleum samples spanning the client-agreed water-content range and relevant liquid states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Obtain water-content comparison values using a reference method agreed with the client.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "For the MIR ATR trial, agree the measurement point and confirm a suitable mid-IR link with AFS rather than using the existing silica cable.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare candidate methods separately on the retained samples against reference water-content values.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Validate each candidate on independent material excluded from calibration, using acceptance criteria agreed with the client before testing.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Proceed only if independent-material performance meets the agreed criteria and AFS confirms the proposed installation; otherwise revise or stop the concept.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Do not treat a retained-sample result as proof of remote in-line performance.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify liquid appearance, link routing, use case and acceptance criteria.",
      "Select retained samples across the agreed water-content range.",
      "Obtain agreed reference water-content values.",
      "Confirm the MIR setup with AFS and compare candidates separately.",
      "Validate on independent material against pre-agreed criteria.",
      "Decide go or no-go from validation and installation feasibility."
    ]
  },
  "decision_basis": [
    {
      "text": "Base the measurement-feasibility decision on comparison with reference water-content values on independent material against criteria agreed with the client before testing.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
